// Build one request per keyword per page (first 5 pages = top 50 results).
// The SearchApi node's num field is ignored by the API, so we page through
// with the page parameter (10 results per page) to get real depth.
const cfg = $('Settings').first().json;
const domain = (cfg.domain || '').trim();
const location = (cfg.location || '').trim();
const PAGES = 5;

const keywords = (cfg.keywords || '')
  .split(',').map(k => k.trim()).filter(k => k.length);

if (!keywords.length) {
  throw new Error('No keywords found. Add a comma-separated list in the Settings node.');
}

const out = [];
for (const keyword of keywords) {
  for (let page = 1; page <= PAGES; page++) {
    out.push({ json: { keyword, domain, location, page } });
  }
}
return out;

// Aggregate each keyword's best organic position across the 5 fetched pages,
// then compare to last week's positions from the Data table.
// SearchApi numbers results 1-10 within each page, so the true rank is
// (page - 1) * 10 + position.

function rootDomain(url) {
  if (!url) return '';
  let h = String(url).replace(/^https?:\/\//i, '').replace(/^www\./i, '');
  h = h.split('/')[0].split('?')[0].toLowerCase();
  return h;
}

const domain = ($('Settings').first().json.domain || '').trim();
const target = rootDomain(domain);
const PER_PAGE = 10;

// Previous positions from the Data table (keyword -> position).
const previous = {};
for (const row of $('Get Previous Ranks').all()) {
  const k = row.json.keyword;
  const p = row.json.position;
  if (k != null && typeof p === 'number') previous[k] = p;
}

// Best (lowest) absolute rank per keyword across all pages.
const best = {};
const seen = [];
for (const item of $input.all()) {
  const serp = item.json || {};
  const sp = serp.search_parameters || {};
  const keyword = sp.q || serp.keyword || '';
  if (!keyword) continue;
  if (!seen.includes(keyword)) seen.push(keyword);

  const page = Number(sp.page || serp.page || 1);
  const organic = Array.isArray(serp.organic_results) ? serp.organic_results : [];
  for (const r of organic) {
    if (rootDomain(r.link || r.domain) === target) {
      const abs = (page - 1) * PER_PAGE + (Number(r.position) || 0);
      if (!best[keyword] || abs < best[keyword].position) {
        best[keyword] = { position: abs, url: r.link || '', title: r.title || '' };
      }
    }
  }
}

const depth = PER_PAGE * 5;
const now = new Date().toISOString();
const results = [];

for (const keyword of seen) {
  const b = best[keyword];
  const position = b ? b.position : null;
  const rankingUrl = b ? b.url : '';
  const title = b ? b.title : '';

  const prev = previous[keyword];
  const hadPrev = typeof prev === 'number';

  let change = null, movement = '';
  if (position == null && !hadPrev) movement = 'Not ranking (top ' + depth + ')';
  else if (position == null && hadPrev) movement = 'Dropped out (was #' + prev + ')';
  else if (!hadPrev) movement = 'New';
  else if (position === prev) { change = 0; movement = 'No change'; }
  else if (position < prev) { change = prev - position; movement = 'Up ' + change; }
  else { change = prev - position; movement = 'Down ' + Math.abs(change); }

  results.push({ json: {
    keyword, domain, position,
    previous_position: hadPrev ? prev : null,
    change, movement, url: rankingUrl, title, last_checked: now
  }});
}

results.sort((a, b) => {
  const av = a.json.change == null ? -1 : Math.abs(a.json.change);
  const bv = b.json.change == null ? -1 : Math.abs(b.json.change);
  return bv - av;
});

return results;

const rows = $input.all().map(i => i.json);
const domain = rows.length ? rows[0].domain : '';
const date = new Date().toISOString().slice(0, 10);

function icon(r) {
  if (r.position == null && r.previous_position == null) return ':white_circle:';
  if (r.position == null) return ':warning:';
  if (r.previous_position == null) return ':new:';
  if (r.change > 0) return ':large_green_circle:';
  if (r.change < 0) return ':red_circle:';
  return ':white_circle:';
}

function detail(r) {
  if (r.position == null && r.previous_position == null) return 'not in top 50';
  if (r.position == null) return 'not in top 50 (was #' + r.previous_position + ')';
  if (r.previous_position == null) return '#' + r.position + ' (new)';
  if (r.change > 0) return '#' + r.position + ' (up ' + r.change + ', was #' + r.previous_position + ')';
  if (r.change < 0) return '#' + r.position + ' (down ' + Math.abs(r.change) + ', was #' + r.previous_position + ')';
  return '#' + r.position + ' (no change)';
}

const lines = rows.map(r => icon(r) + '  *' + r.keyword + '*  -  ' + detail(r));
const up = rows.filter(r => r.change > 0).length;
const down = rows.filter(r => r.change < 0).length;
const fresh = rows.filter(r => r.previous_position == null && r.position != null).length;

let summary = rows.length + ' keywords  ·  ' + up + ' up  ·  ' + down + ' down';
if (fresh) summary += '  ·  ' + fresh + ' new';

// Plain-text fallback (used in notifications / if you drop Slack).
const text = 'SEO Rank Tracker - ' + domain + ' (' + date + ')\n' + lines.join('\n') + '\n' + summary;

// Block Kit layout for a clean Slack message.
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: ':bar_chart: SEO Rank Tracker', emoji: true } },
  { type: 'context', elements: [ { type: 'mrkdwn', text: '*' + domain + '*  ·  ' + date } ] },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: lines.join('\n') } },
  { type: 'divider' },
  { type: 'context', elements: [ { type: 'mrkdwn', text: summary } ] }
];

return [{ json: { text, blocks: JSON.stringify({ blocks }) } }];
